import React, { useState, useEffect, useRef } from "react";
import { ubicacionesData } from "./ubicacionesData";
import "./Ubicaciones.css";

export default function Ubicaciones() {
  const [messages, setMessages] = useState([
    { type: "bot", content: "¿Qué edificio o salón te gustaría saber su ubicación?" },
  ]);
  const [inputValue, setInputValue] = useState("");
  const [showMap, setShowMap] = useState(false);
  const [animateMap, setAnimateMap] = useState(false);
  const chatEndRef = useRef(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const toggleMap = () => {
    if (showMap) {
      setAnimateMap(false);
      setTimeout(() => setShowMap(false), 600);
    } else {
      setShowMap(true);
      setTimeout(() => setAnimateMap(true), 10);
    }
  };

  const handleSendMessage = () => {
    if (!inputValue.trim()) return;

    const userMessage = { type: "user-ub", content: inputValue };
    const botResponse = generateBotResponse(inputValue);

    setMessages((prev) => [...prev, userMessage, ...botResponse]);
    setInputValue("");
  };

  const generateBotResponse = (userInput) => {
    const input = userInput.toLowerCase();
    const ubicacion = ubicacionesData.find(u => input.includes(u.id.toLowerCase()) || input.includes(u.nombre.toLowerCase()));

    if (ubicacion) {
      const response = [{ type: "bot", content: ubicacion.texto }];
      if (ubicacion.imagen) response.push({ type: "bot", content: "building_image", buildingImage: ubicacion.imagen });
      if (ubicacion.acciones) response.push({ type: "bot", content: "", actions: ubicacion.acciones });
      return response;
    }

    return [{ type: "bot", content: "No tengo información sobre esa ubicación." }];
  };

  const handleActionClick = (action) => {
    if (action === "exit") {
      window.location.href = "/";
    }
  };

  const handleMapClick = (ubicacionId) => {
    const ubicacion = ubicacionesData.find(u => u.id === ubicacionId);
    if (!ubicacion) return;
    const userMessage = { type: "user-ub", content: ubicacion.nombre };
    const botResponse = generateBotResponse(ubicacion.nombre);
    setMessages(prev => [...prev, userMessage, ...botResponse]);
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage();
  };

  return (
    <div className="ubicaciones-container">
      <header className="ubicaciones-header">
        <button className="name-button-ub" onClick={() => (window.location.href = "/")}>TalkinPon</button>
        <div className="title-logo-ub"><h1>Ubicaciones</h1>
          <div className="header-right">
            <button onClick={toggleMap} className="map-toggle-btn" title="Mostrar mapa"><i className="bi bi-map-fill"></i></button>
          </div>
        </div>
        <div className="heade-logo-ub"><img src="/logo-app.png" alt="Logo" /></div>
      </header>

      <div className="main-content">
        <div className={`chat-area-ub ${showMap ? "half-width" : "full-width"}`}>
          {messages.map((message, idx) => (
            <div key={idx} className={`message-row-ub ${message.type}`}>
              <img
                src={message.type === "bot" ? "/logo-app.png" : "/img-user.png"}
                alt={message.type === "bot" ? "Bot" : "user-ub"}
                className="avatar-ub"
              />
              <div className="message-with-actions">
                <div className={`message-box-ub ${message.type}`}>
                  {message.content === "building_image" ? (
                    <img src={message.buildingImage} alt="Edificio" className="building-image" />
                  ) : (
                    <p>{message.content}</p>
                  )}
                </div>

                {message.actions && (
                  <div className="actions-row-ub">
                    {message.actions.map((action, i) => (
                      <button
                        key={i}
                        onClick={() => handleActionClick(action.action)}
                        className="action-btn"
                      >
                        {action.label}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={chatEndRef}></div>
        </div>

        {showMap && (
          <>
            <div className={`map-area ${animateMap ? "map-open" : "map-close"}`}>
              <div className="map-header">
                <h3>Mapa del Campus</h3>
                <button onClick={() => { setAnimateMap(false); setTimeout(() => setShowMap(false), 600); }} className="close-map-btn">✕</button>
              </div>

              <div className="map-container">
                <img src="/mapa_tec.png" alt="Mapa Campus" className="campus-map" />
                {ubicacionesData.map(u => (
                  <button
                    key={u.id}
                    className="map-button"
                    style={{ top: u.posicionMapa.top, left: u.posicionMapa.left }}
                    onClick={() => handleMapClick(u.id)}
                  >
                    {u.id}
                  </button>
                ))}
              </div>

              <p className="map-caption">Mapa interactivo del campus universitario</p>
            </div>
            <div className="map-overlay"></div>
          </>
        )}
      </div>

      <div className="input-area p-3 border-top">
        <div className="input-group">
          <input
            type="text"
            className="form-control"
            placeholder="Escribe tu mensaje..."
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={handleKeyPress}
            autoComplete="new-password"
            name="no_autocomplete_field"
          />
          <button className="btn btn-dark" onClick={handleSendMessage}><i className="bi bi-send-fill"></i></button>
        </div>
      </div>
    </div>
  );
}
